import sys

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def base36_encode(n):
    if n == 0:
        return ALPHABET[0]
    chars = []
    while n > 0:
        chars.append(ALPHABET[n % 36])
        n //= 36
    return "".join(reversed(chars))

def base36_decode(s):
    n = 0
    for c in s:
        n = n * 36 + ALPHABET.index(c)
    return n

def next_id(last_id):
    suffix = last_id.split("-", 1)[1]
    n = base36_decode(suffix)
    n += 1
    new_suffix = base36_encode(n).rjust(4, "0")
    return f"ORD-{new_suffix}"

def main():
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        print("ORD-0001")
        return
    last = lines[-1]
    print(next_id(last))

if __name__ == "__main__":
    main()

