#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import os

BASE36_DIGITS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def base36_encode(n: int, width: int) -> str:
    """Encode an integer as a base36 string, zero-padded to width."""
    digits = []
    for _ in range(width):
        n, rem = divmod(n, 36)
        digits.append(BASE36_DIGITS[rem])
    return ''.join(reversed(digits))


def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36_DIGITS.index(ch)
    return n


def main():
    ids_path = os.path.join(os.getcwd(), 'ids.txt')
    with open(ids_path) as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        # No ids yet, start from the beginning
        last_suffix = '0000'
    else:
        last_line = lines[-1]
        last_suffix = last_line.split('-')[1]

    next_val = base36_decode(last_suffix) + 1
    next_suffix = base36_encode(next_val, 4)
    print(f'ORD-{next_suffix}')


if __name__ == '__main__':
    main()

