"""Read ids.txt and print the next order id to stdout."""

import os

BASE36_DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_increment(s: str) -> str:
    """Increment a 4-character base-36 string, with carry."""
    chars = list(s)
    for i in range(3, -1, -1):
        idx = BASE36_DIGITS.index(chars[i])
        if idx < 35:
            chars[i] = BASE36_DIGITS[idx + 1]
            break
        else:
            chars[i] = "0"
    return "".join(chars)


def next_order_id(filepath: str = "ids.txt") -> str:
    """Return the next order id based on the last line of ids.txt."""
    with open(filepath) as f:
        lines = f.readlines()

    # Find the last line that contains a valid order id
    suffix = None
    for line in reversed(lines):
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        for part in parts:
            if part.startswith("ORD-") and len(part) == 8:
                suffix = part[4:]
                break
        if suffix:
            break

    if suffix is None:
        return "ORD-0000"

    return "ORD-" + base36_increment(suffix)


if __name__ == "__main__":
    print(next_order_id())

