#!/usr/bin/env python3
import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_encode(n: int) -> str:
    """Encode an integer as a base-36 string (upper case)."""
    if n == 0:
        return BASE36[0]
    digits = []
    while n > 0:
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def main() -> None:
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    # The most recent id is on the last line.
    # Lines look like: "1\tORD-243C" or "ORD-243C"
    last_line = lines[-1]
    # Find the id part (the word matching ORD-XXXX)
    for token in last_line.split():
        token = token.strip()
        if token.startswith("ORD-"):
            last_id = token
            break
    else:
        print("Error: no ORD- id found in ids.txt", file=sys.stderr)
        sys.exit(1)

    prefix, suffix = last_id.split("-", 1)
    next_num = base36_decode(suffix) + 1
    next_suffix = base36_encode(next_num).zfill(len(suffix))
    print(f"{prefix}-{next_suffix}")


if __name__ == "__main__":
    main()

