import os


def encode_base36(n: int) -> str:
    """Encode an integer as a base-36 string (uppercase)."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return "0"
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result))


def decode_base36(s: str) -> int:
    """Decode a base-36 string (uppercase) to an integer."""
    return int(s, 36)


