        last_code = "0000"
    else:
        last_line = lines[-1]
        last_code = last_line.split("-")[-1]

    last_num = decode_base36(last_code)
    next_num = last_num + 1
    next_code = encode_base36(next_num).zfill(4)

    return f"ORD-{next_code}"


def main():
    ids_path = os.path.join(os.getcwd(), "ids.txt")
    print(next_id(ids_path))


