import sys

CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def to_base36(n: int) -> str:
    """Convert an integer to a base-36 uppercase string (no leading zeros)."""
    if n == 0:
        return '0'
    result = []
    while n > 0:
        result.append(CHARS[n % 36])
        n //= 36
    return ''.join(reversed(result))


def next_id(last_id: str) -> str:
    """Given an id like ORD-243C, return the next id in sequence."""
    suffix = last_id.split('-', 1)[1]
    val = int(suffix, 36)
    val += 1
    next_suffix = to_base36(val).upper().zfill(4)
    return f'ORD-{next_suffix}'


def main() -> None:
    last_id = None
    with open('ids.txt') as f:
        for line in f:
            line = line.strip()
            if line.startswith('ORD-'):
                last_id = line

    if last_id is None:
        print('ORD-0000')
    else:
        print(next_id(last_id))


if __name__ == '__main__':
    main()

