#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events by event_id, write deduped.jsonl."""

import json
import sys


def main() -> None:
    seen: set[str] = set()
    output: list[str] = []

    try:
        with open("events.jsonl") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                event = json.loads(line)
                eid = event.get("event_id")
                if eid is None:
                    print("warning: skipping event with no event_id", file=sys.stderr)
                    continue
                if eid in seen:
                    continue
                seen.add(eid)
                output.append(json.dumps(event, separators=(",", ":")))
    except FileNotFoundError:
        print("error: events.jsonl not found in current directory", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as exc:
        print(f"error: invalid JSON in events.jsonl: {exc}", file=sys.stderr)
        sys.exit(1)

    with open("deduped.jsonl", "w") as f:
        for line in output:
            f.write(line + "\n")

    print(f"deduped.jsonl written ({len(output)} events from {len(seen)} unique IDs)")


if __name__ == "__main__":
    main()

