#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order.

Reports are named report-<n>.txt where <n> counts up from 1. Report order
is numeric, so report-10.txt follows report-9.txt rather than report-2.txt.
Directory iteration order is not stable, so we sort explicitly.
"""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")

_PATTERN = re.compile(r"^report-(\d+)\.txt$")


def report_key(name):
    match = _PATTERN.match(name)
    return int(match.group(1)) if match else (float("inf"), name)


def main():
    try:
        names = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return
    report_names = [name for name in names if _PATTERN.match(name)]
    for name in sorted(report_names, key=report_key):
        print(name)


if __name__ == "__main__":
    main()
