"""List report file names in report order (natural numeric order)."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(__file__), "reports")


def natural_sort_key(filename: str) -> list:
    """Split filename into text and numeric parts for natural sorting."""
    parts = re.split(r"(\d+)", filename)
    # Convert numeric parts to int for proper numeric comparison
    return [int(part) if part.isdigit() else part.lower() for part in parts]


def main() -> None:
    try:
        files = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"Error: directory '{REPORTS_DIR}' not found")
        return

    # Filter to only .txt files (or all files, but reports are .txt)
    report_files = [f for f in files if f.endswith(".txt")]
    report_files.sort(key=natural_sort_key)

    for fname in report_files:
        print(fname)


if __name__ == "__main__":
    main()

