#!/usr/bin/env python3
"""list_reports.py — print report filenames under reports/, in report order."""

from pathlib import Path


def report_sort_key(path: Path) -> int:
    """Extract the report number from a path like reports/report-42.txt."""
    stem = path.stem  # e.g. "report-42"
    # stem is "report-<n>", split on hyphen and take the last piece
    return int(stem.split("-")[-1])


def main() -> None:
    reports_dir = Path("reports")
    if not reports_dir.is_dir():
        return

    files = [p for p in reports_dir.iterdir() if p.suffix == ".txt"]
    files.sort(key=report_sort_key)

    for f in files:
        print(f.name)


if __name__ == "__main__":
    main()

