"""Print report file names under reports/ in report order."""

from pathlib import Path


def report_sort_key(path: Path) -> tuple[int, str]:
    """Sort key that extracts the report number from report-<n>.txt."""
    name = path.name
    if name.startswith("report-") and name.endswith(".txt"):
        num_str = name[len("report-"):-len(".txt")]
        try:
            return (0, int(num_str))
        except ValueError:
            pass
    # Fallback for unexpected filenames
    return (1, name)


def main() -> None:
    reports_dir = Path("reports")
    if not reports_dir.is_dir():
        return

    files = sorted(reports_dir.iterdir(), key=report_sort_key)
    for f in files:
        if f.is_file():
            print(f.name)


if __name__ == "__main__":
    main()

