"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
import os
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse a leading 'YYYY-MM-DD HH:MM:SS' timestamp from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp, got {sys.argv[1]!r}", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff_dt = as_of_dt - timedelta(days=7)

    # Read all entries from app.log
    log_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "app.log")
    archive_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "archive.log")

    try:
        with open(log_path, "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    # Remove trailing newlines for consistent handling
    lines = [line.rstrip("\n") for line in lines]

    # Filter out empty trailing lines
    while lines and lines[-1] == "":
        lines.pop()

    old_entries: list[str] = []
    kept_entries: list[str] = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff_dt:
            old_entries.append(line)
        else:
            kept_entries.append(line)

    # Append old entries to archive.log
    with open(archive_path, "a") as f:
        for entry in old_entries:
            f.write(entry + "\n")

    # Rewrite app.log with kept entries
    with open(log_path, "w") as f:
        for entry in kept_entries:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()

