#!/usr/bin/env python3
"""Rotate old entries from app.log to archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message. Entries
whose timestamp is strictly older than 7 days before AS_OF are moved to
archive.log (appended, preserving order). Remaining entries rewrite app.log
in their original order.
"""

import datetime
import sys
from pathlib import Path


def parse_ts(line: str) -> datetime.datetime | None:
    """Return the datetime of the line, or None if it can't be parsed."""
    try:
        ts_str = line[:19]
        return datetime.datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer, got {sys.argv[1]!r}", file=sys.stderr)
        sys.exit(1)

    cutoff_dt = datetime.datetime.utcfromtimestamp(as_of) - datetime.timedelta(days=7)

    repo_root = Path(__file__).resolve().parent
    app_log = repo_root / "app.log"
    archive_log = repo_root / "archive.log"

    if not app_log.exists():
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    with open(app_log, "r") as f:
        lines = f.readlines()

    old_entries: list[str] = []
    kept_entries: list[str] = []

    for line in lines:
        stripped = line.rstrip("\n")
        if not stripped.strip():
            continue
        dt = parse_ts(stripped)
        if dt is not None and dt < cutoff_dt:
            old_entries.append(stripped)
        else:
            kept_entries.append(stripped)

    if old_entries:
        with open(archive_log, "a") as f:
            for entry in old_entries:
                f.write(entry + "\n")

    with open(app_log, "w") as f:
        for entry in kept_entries:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()
